import subprocess, os, ctypes, torch, re, collections, statistics
os.makedirs('/tmp/r5e2', exist_ok=True)
src = r'''
#include <cuda_runtime.h>
#include <cuda.h>
#include <cstdint>
struct Cfg { int nk, S, n1, n2, nacc, rot, ring, feed, we, real, kb_mod, wtiles; };
__device__ __forceinline__ uint32_t smem_u32(const void* p) { return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ bool try_wait(uint32_t bar, uint32_t par) {
  uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }" : "=r"(ok) : "r"(bar), "r"(par) : "memory");
  return ok != 0;
}
__device__ __forceinline__ void mbar_wait(uint32_t bar, uint32_t par) { uint32_t n = 0; while (!try_wait(bar, par)) if (++n > (1u << 26)) __trap(); }
__device__ __forceinline__ uint32_t elect_one() {
  uint32_t pred = 0;
  asm volatile("{\n .reg .b32 rx;\n .reg .pred px;\n elect.sync rx|px, %1;\n selp.b32 %0, 1, 0, px;\n}" : "=r"(pred) : "r"(0xffffffffu));
  return pred;
}
__device__ __forceinline__ uint32_t mapa0(uint32_t a) { uint32_t r; asm volatile("mapa.shared::cluster.u32 %0, %1, %2;" : "=r"(r) : "r"(a), "r"(0)); return r; }
__device__ __forceinline__ uint64_t sw128_desc(uint32_t addr) {
  return (uint64_t)((addr & 0x3FFFF) >> 4) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | ((uint64_t)1 << 46) | ((uint64_t)2 << 61);
}
__device__ __forceinline__ uint64_t gtime() { uint64_t t; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); return t; }
template <int CG> __device__ __forceinline__ void mma(uint32_t t, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  if constexpr (CG == 2) asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::2.kind::tf32 [%0], %1, %2, %3, p; }" ::"r"(t), "l"(a), "l"(b), "r"(id), "r"(acc));
  else asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::1.kind::tf32 [%0], %1, %2, %3, p; }" ::"r"(t), "l"(a), "l"(b), "r"(id), "r"(acc));
}
template <int CG> __device__ __forceinline__ void commit(uint32_t bar) {
  if constexpr (CG == 2) asm volatile("tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1;" ::"r"(bar), "h"((uint16_t)3) : "memory");
  else asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];" ::"r"(bar) : "memory");
}
template <int CG> __device__ __forceinline__ void tma(uint32_t dst, const CUtensorMap* m, uint32_t bar, int x, int y, uint64_t pol) {
  if constexpr (CG == 2) asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1, {%3, %4}], [%2], %5;" ::"r"(dst), "l"((uint64_t)m), "r"(bar), "r"(x), "r"(y), "l"(pol) : "memory");
  else asm volatile("cp.async.bulk.tensor.2d.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1, {%3, %4}], [%2], %5;" ::"r"(dst), "l"((uint64_t)m), "r"(bar), "r"(x), "r"(y), "l"(pol) : "memory");
}
template <int CG> __device__ __forceinline__ void csync() {
  if constexpr (CG == 2) asm volatile("barrier.cluster.arrive.release.aligned;\nbarrier.cluster.wait.acquire.aligned;" ::: "memory");
  else __syncthreads();
}
template <int CG, int UNI>
__global__ void __launch_bounds__(128, 1) ringk(const __grid_constant__ CUtensorMap mapW, const __grid_constant__ CUtensorMap mapE1,
    const __grid_constant__ CUtensorMap mapE2, Cfg c, unsigned long long* out) {
  extern __shared__ uint8_t smem_raw[];
  __shared__ __align__(8) uint64_t full[16], empty[16], accum;
  __shared__ uint32_t tmem_slot;
  const uint32_t sbase = (smem_u32(smem_raw) + 1023) & ~1023u;
  const int eb1 = c.n1 / CG, eb2 = c.n2 / CG;
  const uint32_t stageBytes = 16384 + (eb1 + eb2) * 128;
  const int warp = __shfl_sync(0xffffffff, threadIdx.x >> 5, 0);
  const int lane = threadIdx.x & 31;
  uint32_t rank = 0;
  if constexpr (CG == 2) asm volatile("mov.u32 %0, %%cluster_ctarank;" : "=r"(rank));
  const uint32_t tcols = c.nacc == 2 ? 512 : 256;
  if (threadIdx.x == 0) {
    for (int i = 0; i < c.S; ++i) {
      asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" ::"r"(smem_u32(&full[i])));
      asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" ::"r"(smem_u32(&empty[i])));
    }
    asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" ::"r"(smem_u32(&accum)));
    asm volatile("fence.mbarrier_init.release.cluster;");
  }
  if (warp == 3) {
    if constexpr (CG == 2) {
      asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_u32(&tmem_slot)), "r"(tcols));
      asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;");
    } else {
      asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_u32(&tmem_slot)), "r"(tcols));
      asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
    }
  }
  asm volatile("tcgen05.fence::before_thread_sync;");
  csync<CG>();
  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint32_t tmem = tmem_slot;
  const int wrow = c.real ? blockIdx.x * 128 : (blockIdx.x % c.wtiles) * 128;
  if (warp == 0 && c.ring == 2) {
    if (UNI || lane == 0) {
      uint64_t pol;
      asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
      for (int i = 0; i < c.nk; ++i) {
        const int s = i % c.S;
        if (i >= c.S) mbar_wait(smem_u32(&empty[s]), ((i / c.S) - 1) & 1);
        if (!UNI || elect_one()) {
          const uint32_t fl = smem_u32(&full[s]);
          if (c.feed) {
            const uint32_t fb = CG == 2 ? mapa0(fl) : fl;
            if (rank == 0) asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(fl), "r"(CG * stageBytes) : "memory");
            const uint32_t a = sbase + s * stageBytes, b = a + 16384;
            const int kb = i % c.kb_mod;
            tma<CG>(a, &mapW, fb, kb * 32, wrow, pol);
            tma<CG>(b, &mapE1, fb, kb * 32, rank * eb1, pol);
            if (c.nacc == 2) tma<CG>(b + eb1 * 128, &mapE2, fb, kb * 32, CG * eb1 + rank * eb2, pol);
          } else if (rank == 0) {
            asm volatile("mbarrier.arrive.shared::cta.b64 _, [%0];" ::"r"(fl) : "memory");
          }
        }
        if (UNI) __syncwarp();
      }
    }
  } else if (warp == 1 && rank == 0) {
    if (UNI || lane == 0) {
      const uint32_t idesc1 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(c.n1 >> 3) << 17) | ((uint32_t)(CG * 128 >> 4) << 24);
      const uint32_t idesc2 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(c.n2 >> 3) << 17) | ((uint32_t)(CG * 128 >> 4) << 24);
      const uint64_t t0 = clock64(), g0 = gtime();
      for (int i = 0; i < c.nk; ++i) {
        const int s = c.rot ? i % c.S : 0;
        if (c.ring == 2) mbar_wait(smem_u32(&full[s]), (i / c.S) & 1);
        else if (c.ring == 1 && i >= c.S && (s % c.we) == 0) mbar_wait(smem_u32(&empty[s]), ((i / c.S) - 1) & 1);
        asm volatile("tcgen05.fence::after_thread_sync;");
        const uint32_t a = sbase + s * stageBytes, b = a + 16384;
        const uint64_t da = sw128_desc(a), db = sw128_desc(b), db2 = sw128_desc(b + eb1 * 128);
        if (!UNI || elect_one()) {
#pragma unroll
          for (int k = 0; k < 4; ++k) {
            const uint32_t acc = (i | k) != 0;
            mma<CG>(tmem, da + 2 * k, db + 2 * k, idesc1, acc);
            if (c.nacc == 2) mma<CG>(tmem + 256, da + 2 * k, db2 + 2 * k, idesc2, acc);
          }
          commit<CG>(smem_u32(&empty[s]));
        }
        if (UNI) __syncwarp();
      }
      if (!UNI || elect_one()) commit<CG>(smem_u32(&accum));
      if (UNI) __syncwarp();
      mbar_wait(smem_u32(&accum), 0);
      const uint64_t t1 = clock64(), g1 = gtime();
      if (lane == 0) { out[blockIdx.x * 3] = t1 - t0; out[blockIdx.x * 3 + 1] = g1 - g0; out[blockIdx.x * 3 + 2] = 1; }
    }
  }
  __syncwarp();
  mbar_wait(smem_u32(&accum), 0);
  asm volatile("tcgen05.fence::before_thread_sync;");
  csync<CG>();
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    if constexpr (CG == 2) asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(tcols));
    else asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(tcols));
  }
}
template <int CG, int UNI>
int go(CUtensorMap& a, CUtensorMap& b, CUtensorMap& d, Cfg c, unsigned long long* out, int grid, size_t smem, cudaStream_t st) {
  auto k = ringk<CG, UNI>;
  cudaFuncSetAttribute(k, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid); cfg.blockDim = dim3(128); cfg.dynamicSmemBytes = smem; cfg.stream = st;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = CG; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = CG == 2 ? 1 : 0;
  cudaLaunchKernelEx(&cfg, k, a, b, d, c, out);
  return (int)cudaGetLastError();
}
extern "C" int launch(int cg, int uni, const void* W, int wrows, const void* E, int erows, Cfg c, unsigned long long* out, int grid, cudaStream_t st) {
  CUtensorMap mW, mE1, mE2;
  int eb1 = c.n1 / cg, eb2 = c.n2 / cg; if (eb2 < 8) eb2 = 8;
  auto enc = [&](CUtensorMap* m, const void* p, int rows, int boxr) -> int {
    cuuint64_t d[2] = {3072, (cuuint64_t)rows}, s[1] = {3072 * 4};
    cuuint32_t b[2] = {32, (cuuint32_t)boxr}, e[2] = {1, 1};
    return (int)cuTensorMapEncodeTiled(m, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)p, d, s, b, e, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  };
  if (enc(&mW, W, wrows, 128)) return 1001;
  if (enc(&mE1, E, erows, eb1)) return 1002;
  if (enc(&mE2, E, erows, eb2)) return 1003;
  size_t stageBytes = 16384 + (c.n1 / cg + c.n2 / cg) * 128;
  size_t smem = c.S * stageBytes + 1024;
  if (cg == 2 && uni) return go<2, 1>(mW, mE1, mE2, c, out, grid, smem, st);
  if (cg == 2) return go<2, 0>(mW, mE1, mE2, c, out, grid, smem, st);
  if (uni) return go<1, 1>(mW, mE1, mE2, c, out, grid, smem, st);
  return go<1, 0>(mW, mE1, mE2, c, out, grid, smem, st);
}
'''
open('/tmp/r5e2/ring.cu','w').write(src)
r = subprocess.run(['nvcc','-O3','-std=c++17','-gencode','arch=compute_100a,code=sm_100a','-shared','-Xcompiler','-fPIC','-o','/tmp/r5e2/ring.so','/tmp/r5e2/ring.cu','-lcuda'], capture_output=True, text=True)
print(r.returncode, r.stderr[-2500:])
sass = subprocess.run(['cuobjdump','-sass','/tmp/r5e2/ring.so'], capture_output=True, text=True).stdout
funcs = re.split(r'\n\s+Function : ', sass)[1:]
for f in funcs:
    name = f.split('\n')[0].strip()
    ops = re.findall(r'/\*[0-9a-f]{4}\*/\s+(?:@!?U?P\w+\s+)?([A-Z][A-Z0-9_.]+)', f)
    cnt = collections.Counter(o.split('.')[0] for o in ops)
    keys = ['UTCHMMA','UTCQMMA','UTCOMMA','UTCMMA','UTCBAR','R2UR','VOTEU','ELECT','SYNCS','UTMALDG','BRA','PLOP3','UMOV','R2UR']
    print(name[:40], len(ops), {k:cnt[k] for k in keys if cnt[k]})
    idx = [i for i,o in enumerate(ops) if 'MMA' in o and o.startswith('UTC')]
    if idx:
        print('  loop region:', ' '.join(o for o in ops[max(0,idx[0]-25):idx[-1]+8]))
lib = ctypes.CDLL('/tmp/r5e2/ring.so')
class Cfg(ctypes.Structure):
    _fields_ = [(n, ctypes.c_int) for n in ['nk','S','n1','n2','nacc','rot','ring','feed','we','real','kb_mod','wtiles']]
lib.launch.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_int, Cfg, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
W = torch.randn(18432, 3072, device='cuda') / 55
E = torch.randn(512, 3072, device='cuda')
def run(cg, uni, n1, n2, S, rot, ring, feed=0, we=1, nk=384, grid=148):
    nacc = 2 if n2 else 1
    c = Cfg(nk, S, n1, n2, nacc, rot, ring, feed, we, 0, 96, 16)
    out = torch.zeros(grid*3, dtype=torch.int64, device='cuda')
    st = torch.cuda.current_stream().cuda_stream
    for _ in range(2):
        e = lib.launch(cg, uni, W.data_ptr(), 18432, E.data_ptr(), 512, c, out.data_ptr(), grid, st)
        assert e == 0, e
        torch.cuda.synchronize()
    o = out.view(grid,3).cpu()
    o = o[o[:,2]==1]
    clk = statistics.median(o[:,0].tolist())/nk
    mhz = statistics.median((o[:,0].double()/o[:,1].double()*1000).tolist())
    return clk, mhz
variants = [('a fixed nobar',0,0,0),('b rot nobar',1,0,0),('c ring we1',1,1,0),('d ring we2',1,1,0),('d ring we4',1,1,0),('e 2warp res',1,2,0),('f 2warp fed',1,2,1)]
res = collections.defaultdict(list); mh=[]
for rnd in range(3):
    for cg in (2,1):
        for (N, n1, n2, S) in ((192,192,0,4),(384,256,128,4 if cg==2 else 3)):
            for uni in (0,1):
                for (name, rot, ring, feed) in variants:
                    we = int(name[-1]) if name.startswith('d') else 1
                    clk, mhz = run(cg, uni, n1, n2, S, rot, ring, feed, we)
                    res[(cg,N,uni,name)].append(clk); mh.append(mhz)
print('MHz range %.0f-%.0f' % (min(mh), max(mh)))
for cg in (2,1):
    for N in (192,384):
        print(f'--- {cg}SM N={N} MMA={2*N if True else 0} clk/stage: uni0 | uni1 (3 rounds)')
        for (name,_,_,_) in variants:
            a = res[(cg,N,0,name)]; b = res[(cg,N,1,name)]
            print(f'{name:12s} ' + ' '.join('%5.0f'%x for x in a) + ' | ' + ' '.join('%5.0f'%x for x in b))

